<script setup lang="ts">
import { computed } from 'vue';
import { route as routeSource,go,setQuery,back } from '../workbench/navigation';
import { mode } from '../workbench/store';
import { learningSpaces,spaceChapters,spaceClaims,spaceRequirements,requirementIssues,assessmentFor,adoptedDefinitions,lastActivity } from '../workbench/learning-space-mock';
import { studentRoster,learnerSpaces,learnerActivities,latestLearning,manualQuestions,targetCounts,beliefUpdates,aspectChangedAt,currentJudgment,aspectText } from '../workbench/student-state';
import { dateMatches } from '../workbench/runtime-observation';
import { auditActivities,evidenceOrigin,executionNames,reviewNames } from '../workbench/activity-review-mock';
import { defaultAspectNames } from '../workbench/evaluation-mock';
import AccessGate from './AccessGate.vue';
import WorkbenchDialog from './WorkbenchDialog.vue';
import PagingBar from './PagingBar.vue';
const route=routeSource,location=window.location;
const roster=computed(studentRoster),student=computed(()=>roster.value.find(s=>s.id===route.id));
const spaces=computed(()=>learnerSpaces(route.id));
const space=computed(()=>spaces.value.find(s=>s.id===route.scope));
const dateError=computed(()=>route.range==='custom'&&route.since&&route.until&&route.since>route.until);
const inPeriod=(at:string)=>dateMatches(at,route.range||'all',route.since,route.until);
const books=[...new Map(learningSpaces.map(s=>[s.adopted.book.id,s.adopted.book.name])).entries()];
const periodActivities=(id:string)=>learnerActivities(id).filter(r=>inPeriod(r.activity.at));
const students=computed(()=>roster.value.filter(s=>(s.name+' '+s.id).toLowerCase().includes(route.q.trim().toLowerCase())&&(!route.filter||learnerSpaces(s.id).some(ls=>ls.adopted.book.id===route.filter))&&(!route.status||(route.status==='with'?periodActivities(s.id).length>0:route.status==='without'?periodActivities(s.id).length===0:route.status==='review'?manualQuestions(s.id).length>0:false))).sort((a,b)=>route.sort==='name'?a.name.localeCompare(b.name,'zh-CN'):route.sort==='activities'?periodActivities(b.id).length-periodActivities(a.id).length:latestLearning(b.id).localeCompare(latestLearning(a.id))));
const listPage=computed(()=>Math.min(route.p,Math.max(1,Math.ceil(students.value.length/10))));
const tabs={state:'能力状态',changes:'变化与依据',activities:'学习活动'};
const tab=computed(()=>Object.prototype.hasOwnProperty.call(tabs,route.tab)?route.tab:'state');
const claims=computed(()=>space.value?spaceClaims(space.value):[]),chapters=computed(()=>space.value?spaceChapters(space.value):[]);
const invalidFilter=computed(()=>!!space.value&&((!!route.claim&&!claims.value.some(c=>c.id===route.claim))||(!!route.chapter&&!chapters.value.some(ch=>ch.id===route.chapter))));
const requirements=computed(()=>space.value?spaceRequirements(space.value).filter(r=>(!route.claim||r.selection.claimId===route.claim)&&(!route.chapter||r.requirement.chapterIds.includes(route.chapter))):[]);
const visibleClaims=computed(()=>claims.value.filter(c=>(!route.claim||c.id===route.claim)&&(!route.chapter||requirements.value.some(r=>r.selection.claimId===c.id))));
const aspectColumns=computed(()=>[...new Map(visibleClaims.value.flatMap(c=>c.aspects.map(a=>[a.id,a.name] as const))).entries()]);
const activities=computed(()=>space.value?auditActivities().filter(r=>r.space.id===space.value!.id&&inPeriod(r.activity.at)&&(!route.chapter||r.activity.chapterId===route.chapter)&&(!route.claim||r.audit?.claimId===route.claim||r.activity.evidence.some(e=>e.claimId===route.claim))).sort((a,b)=>b.activity.at.localeCompare(a.activity.at)):[]);
const updates=computed(()=>space.value?beliefUpdates(space.value).filter(r=>inPeriod(r.activity.at)&&(!route.chapter||r.activity.chapterId===route.chapter)&&(!route.claim||r.audit.claimId===route.claim)):[]);
const changes=computed(()=>space.value?adoptedDefinitions(space.value).filter(d=>d.changed):[]);
const spaceHistory=computed(()=>space.value?.history.filter(h=>inPeriod(h.at))||[]);
const detailParts=computed(()=>route.result.split(':'));
const detailKind=computed(()=>detailParts.value[0]),detailId=computed(()=>detailParts.value[1]||'');
const detailClaim=computed(()=>claims.value.find(c=>c.id===detailId.value));
const detailEvidence=computed(()=>space.value?evidenceOrigin(space.value.id,detailId.value):undefined);
const detailRequirement=computed(()=>space.value?spaceRequirements(space.value).find(r=>r.requirement.id===detailId.value):undefined);
const detailChange=computed(()=>space.value?beliefUpdates(space.value).find(r=>r.id===detailParts.value.slice(1).join(':')):undefined);
const validDetail=computed(()=>detailKind.value==='belief'||detailKind.value==='definition'?!!detailClaim.value:detailKind.value==='evidence'?!!detailEvidence.value:detailKind.value==='requirement'?!!detailRequirement.value:detailKind.value==='change'?!!detailChange.value:false);
const titles:Record<string,string>={belief:'个人 Belief 与证据',definition:'采用的 Task Claim',evidence:'Evidence 与原始表现',requirement:'学习要求与目标结果',change:'本轮判断变化与依据'};
const detailTitle=computed(()=>validDetail.value?titles[detailKind.value!]:'未找到对应记录');
const dates=()=>({range:route.range,since:route.since,until:route.until});
function openStudent(id:string){go('students',{id,...dates(),returnTo:location.hash});}
function openSpace(id:string){go('students',{id:route.id,scope:id,tab:'state',...dates(),returnTo:location.hash});}
function selectTab(value:string){setQuery({tab:value,result:'',p:1});}
function show(kind:string,id:string){setQuery({result:kind+':'+id});}
function owner(page:string,values:Record<string,string>){go(page,{...values,returnTo:location.hash});}
function trace(id:string,round='',span='',tab='process'){owner('activity',{id,round,span,tab});}
function evidenceTrace(id:string){if(!space.value)return;const e=evidenceOrigin(space.value.id,id);if(!e)return;const row=auditActivities().find(r=>r.space.id===space.value!.id&&r.activity.id===e.activity.id),round=row?.audit?.rounds.find(r=>r.evidenceIds.includes(id));trace(e.activity.id,round?.id,round?round.id+'-evidence':'');}
function backLevel(){if(route.returnTo)back('students');else go('students',route.scope?{id:route.id}:{});}
function resetFilters(){setQuery({q:'',filter:'',status:'',sort:'',range:'all',since:'',until:'',p:1,claim:'',chapter:'',result:''});}
const aspect=(id:string)=>(defaultAspectNames as Record<string,string>)[id]||id;
const chapterName=(id:string)=>space.value?.adopted.book.units.flatMap(u=>u.chapters).find(ch=>ch.id===id)?.name||id;
const taskName=(id:string)=>space.value?.adopted.domain.tasks.find(t=>t.id===id)?.name||id;
const methodNames=(ids:string[])=>ids.map(id=>space.value?.adopted.domain.methods.find(m=>m.id===id)?.name||id).join('、');
const claimBasis=(id:string)=>[...new Set(space.value?.judgments.filter(j=>j.claimId===id).flatMap(j=>j.evidenceIds)||[])];
const safePage=(count:number)=>Math.min(route.p,Math.max(1,Math.ceil(count/10)));
</script>
<template><div class="wb-page student-state-workspace">
  <section v-if="mode==='real'" class="panel"><h2>尚未接入真实学生状态</h2><p>当前真实对话没有正式学生身份和 Evaluation 结果，不能用示例 Belief 代替。可到交互审查查看真实会话。</p><button class="btn" @click="go('trace-list')">查看真实会话 →</button></section>
  <template v-else>
    <header class="page-header student-state-header"><div><button v-if="route.id" class="text-link" @click="backLevel">← {{route.returnTo.startsWith('#/users')?'返回用户管理':route.returnTo.startsWith('#/activity')?'返回交互审查':route.returnTo.startsWith('#/objects')?'返回空间观测':route.returnTo.startsWith('#/learning-spaces')?'返回学习空间':route.scope?'返回学生概览':'返回学生列表'}}</button><h2>{{!route.id?'学生状态':student?(space?student.name+' · '+space.name:student.name):'未找到学生'}}</h2><p class="page-desc">{{!route.id?'从学生出发，查看各课程内的判断、目标结果与学习依据。':student?student.id+(space?' · '+space.id:' · 各学习空间的能力状态分别维护'):'不会用其他学生的记录替代。'}}</p></div><span class="badge">Mock · 人工示例</span></header>
    <section v-if="route.id&&(!student||(route.scope&&!space))" class="panel"><p role="alert">{{!student?'所选学生不在当前课程示例中。':'所选学习空间不属于这位学生或已不存在。'}}</p><button class="btn" @click="go('students')">返回学生列表</button></section>
    <template v-else>
      <div class="toolbar date-toolbar"><label>记录时间<select aria-label="记录时间" :value="route.range||'all'" @change="setQuery({range:($event.target as HTMLSelectElement).value,p:1})"><option value="all">全部记录</option><option value="7days">近 7 天</option><option value="30days">近 30 天</option><option value="custom">自定义日期</option></select></label><template v-if="route.range==='custom'"><label>开始日期<input type="date" :value="route.since" @input="setQuery({since:($event.target as HTMLInputElement).value,p:1})"/></label><label>结束日期<input type="date" :value="route.until" @input="setQuery({until:($event.target as HTMLInputElement).value,p:1})"/></label></template><p class="muted">时间筛选只影响活动与历史记录；当前能力和目标结果不随日期回退。</p></div>
      <p v-if="dateError" class="callout danger" role="alert">开始日期不能晚于结束日期。</p>
      <template v-else-if="!route.id">
        <div class="metric-grid student-metrics"><div class="metric-card"><span>示例学生</span><strong>{{roster.length}}</strong><small>当前课程示例中的身份</small></div><div class="metric-card"><span>期间有活动的学生</span><strong>{{roster.filter(s=>periodActivities(s.id).length).length}}</strong><small>没有活动不等于能力不足</small></div><div class="metric-card"><span>期间学习活动</span><strong>{{roster.reduce((n,s)=>n+periodActivities(s.id).length,0)}}</strong><small>按活动计数，不按消息数</small></div><div class="metric-card"><span>当前人工疑点</span><strong>{{roster.reduce((n,s)=>n+manualQuestions(s.id).length,0)}}</strong><small>交互审查中尚待核对的活动</small></div></div>
        <div class="toolbar student-filters"><label class="search-label">查找学生<input type="search" :value="route.q" placeholder="姓名或编号" @input="setQuery({q:($event.target as HTMLInputElement).value,p:1})"/></label><label>教材<select aria-label="筛选教材" :value="route.filter" @change="setQuery({filter:($event.target as HTMLSelectElement).value,p:1})"><option value="">全部教材</option><option v-for="[id,name] in books" :key="id" :value="id">{{name}}</option></select></label><label>记录情况<select aria-label="记录情况" :value="route.status" @change="setQuery({status:($event.target as HTMLSelectElement).value,p:1})"><option value="">全部</option><option value="with">期间有活动</option><option value="without">期间无活动</option><option value="review">有人工疑点</option></select></label><label>排序<select aria-label="学生排序" :value="route.sort||'recent'" @change="setQuery({sort:($event.target as HTMLSelectElement).value,p:1})"><option value="recent">最近学习优先</option><option value="activities">期间活动数</option><option value="name">学生姓名</option></select></label><button class="btn" @click="resetFilters">重置筛选</button></div>
        <p class="muted">共 {{students.length}} 位符合筛选的学生；上方摘要为当前示例全体统计。</p>
        <section class="table-card scroll-table"><table class="data-table student-list"><thead><tr><th>学生</th><th>学习空间</th><th>期间活动</th><th>最近学习</th><th>人工疑点</th><th></th></tr></thead><tbody><tr v-for="s in students.slice((listPage-1)*10,listPage*10)" :key="s.id"><td><button class="text-link item-name" @click="openStudent(s.id)">{{s.name}}</button><small>{{s.id}}</small></td><td>{{learnerSpaces(s.id).length}} 个<small>{{learnerSpaces(s.id).map(ls=>ls.name).join('、')}}</small></td><td>{{periodActivities(s.id).length}} 次</td><td>{{latestLearning(s.id)||'尚无记录'}}<small>全部记录中的最近一次</small></td><td><span :class="manualQuestions(s.id).length?'badge amber':'muted'">{{manualQuestions(s.id).length}} 项</span></td><td><button class="btn" :aria-label="'查看学生 '+s.id" @click="openStudent(s.id)">查看状态 →</button></td></tr></tbody></table><p v-if="!students.length" class="empty">没有符合条件的学生。</p></section><PagingBar v-if="students.length>10" :total="students.length" :page="listPage"/>
        <details><summary>示例范围</summary><p class="muted">与当前学习空间、Claim、交互审查共用示例，不是正式学生账户名册。旧版身份不按同名自动合并。</p><button class="text-link" @click="go('students',{source:'legacy'})">查看旧版个人记录 →</button></details>
      </template>
      <AccessGate v-else-if="!dateError&&student" :subject="student.id">
        <template v-if="!space">
          <div class="metric-grid student-metrics"><div class="metric-card"><span>学习空间</span><strong>{{spaces.length}}</strong><small>能力状态分开查看</small></div><div class="metric-card"><span>已有学习记录的空间</span><strong>{{spaces.filter(s=>s.activities.length).length}}</strong><small>按全部学习记录计数</small></div><div class="metric-card"><span>期间学习活动</span><strong>{{periodActivities(student.id).length}}</strong><small>跨空间只汇总活动次数</small></div><div class="metric-card"><span>当前人工疑点</span><strong>{{manualQuestions(student.id).length}}</strong><small>沿原活动核对，不代表能力不足</small></div></div>
          <div class="section-heading"><h3>各课程的学习状态</h3><span class="muted">不生成跨课程平均掌握率</span></div>
          <section class="table-card scroll-table"><table class="data-table student-space-list"><thead><tr><th>学习空间 / 采用内容</th><th>课程范围</th><th>目标结果 · 要求项数</th><th>学习记录</th><th></th></tr></thead><tbody><tr v-for="s in spaces" :key="s.id"><td><button class="text-link item-name" @click="openSpace(s.id)">{{s.name}}</button><small>{{s.id}} · {{s.adopted.book.name}} v{{s.adopted.book.revision}}</small><small>{{s.adopted.target.name}} v{{s.adopted.target.revision}}</small></td><td>{{spaceChapters(s).length}} 章<small>{{spaceClaims(s).length}} 项 Task Claim</small></td><td><div class="result-badges"><span v-for="(n,label) in targetCounts(s)" :key="label">{{label}} <strong>{{n}}</strong></span></div><small>按本空间采用的目标要求比较</small></td><td>{{s.activities.length}} 次活动<small>{{lastActivity(s)||'尚无学习记录'}}</small></td><td><button class="btn" :aria-label="'查看空间状态 '+s.id" @click="openSpace(s.id)">查看状态 →</button></td></tr></tbody></table></section>
          <div class="section-heading"><h3>最近学习活动</h3><span class="muted">所选期间，最多显示 5 次；更多记录在具体空间查看</span></div><section class="panel"><div v-for="r in periodActivities(student.id).slice(0,5)" :key="r.activity.id" class="list-row"><div><button class="text-link" @click="trace(r.activity.id)">{{r.activity.name}}</button><small>{{r.space.name}} · {{r.activity.kind}}</small></div><span class="muted">{{r.activity.at}}</span></div><p v-if="!periodActivities(student.id).length" class="empty">所选期间没有学习活动。</p></section>
        </template>
        <template v-else>
          <section class="course-context"><div><strong>{{space.adopted.book.name}} · v{{space.adopted.book.revision}}</strong><p>{{space.adopted.target.name}} · v{{space.adopted.target.revision}} · {{chapters.length}} 个所选章节</p></div><div class="button-row"><button class="btn" @click="owner('learning-spaces',{id:space.id})">课程范围与采用版本 →</button><button class="text-link" @click="owner('objects',{tab:'Evaluation',scope:space.id})">空间观测 →</button></div></section>
          <div class="tabs" role="tablist" aria-label="学生空间状态"><button v-for="(name,key) in tabs" :key="key" role="tab" :aria-selected="tab===key" :class="{active:tab===key}" @click="selectTab(key)">{{name}}</button></div>
          <div class="toolbar scope-filters"><label>教材章节<select aria-label="教材章节" :value="route.chapter" @change="setQuery({chapter:($event.target as HTMLSelectElement).value,p:1,result:''})"><option value="">全部所选章节</option><option v-if="route.chapter&&!chapters.some(c=>c.id===route.chapter)" :value="route.chapter">{{route.chapter}} · 不在本空间</option><option v-for="ch in chapters" :key="ch.id" :value="ch.id">{{ch.name}}</option></select></label><label>Task Claim<select aria-label="筛选 Task Claim" :value="route.claim" @change="setQuery({claim:($event.target as HTMLSelectElement).value,p:1,result:''})"><option value="">全部采用的 Claim</option><option v-if="route.claim&&!claims.some(c=>c.id===route.claim)" :value="route.claim">{{route.claim}} · 未采用</option><option v-for="c in claims" :key="c.id" :value="c.id">{{c.name}}</option></select></label><button v-if="route.chapter||route.claim" class="text-link" @click="setQuery({chapter:'',claim:'',p:1,result:''})">清除章节与 Claim 筛选</button></div>
          <p v-if="invalidFilter" role="alert" class="callout amber">章节或 Claim 不属于此空间，未借用其他范围的判断。</p>
          <template v-else-if="tab==='state'">
            <div class="section-heading"><div><h3>个人能力判断 · Belief</h3><p class="muted">每项 Claim 分方面保留判断和证据；“尚未形成判断”不是能力为零。</p></div><span class="muted">{{visibleClaims.length}} 项 Claim</span></div>
            <section class="table-card scroll-table"><table class="data-table student-beliefs"><thead><tr><th>Task Claim / 任务</th><th v-for="[id,name] in aspectColumns" :key="id">{{name}}</th><th></th></tr></thead><tbody><tr v-for="c in visibleClaims" :key="c.id"><td><button class="text-link item-name" @click="show('belief',c.id)">{{c.name}}</button><small>{{taskName(c.taskId)}}</small><small>{{c.id}} · 采用 v{{c.version}}</small></td><td v-for="[id] in aspectColumns" :key="id"><span :class="{'muted':!currentJudgment(space,c.id,id)}">{{aspectText(space,c.id,id)}}</span></td><td><button class="text-link" :aria-label="'查看个人判断 '+c.id" @click="show('belief',c.id)">判断与证据 →</button></td></tr></tbody></table><p v-if="!visibleClaims.length" class="empty">此范围尚无采用的 Task Claim。不能将内容准备缺口当作学生未掌握。</p></section>
            <div class="section-heading goal-heading"><div><h3>目标达成结果</h3><p class="muted">将个人判断与具体要求比较；这些数量统计学习要求，不表示掌握比例。</p></div><div class="result-badges"><span v-for="(n,label) in targetCounts(space,route.claim,route.chapter)" :key="label">{{label}} <strong>{{n}}</strong></span></div></div>
            <section class="table-card scroll-table"><table class="data-table student-targets"><thead><tr><th>具体学习要求</th><th>当前结果</th><th>依据与待确认原因</th><th></th></tr></thead><tbody><tr v-for="r in requirements" :key="r.requirement.id"><td>{{r.requirement.name}}<small>{{r.requirement.chapterIds.map(chapterName).join('、')}} · {{r.requirement.aspectIds.map(aspect).join('、')}}</small></td><td><span class="badge" :class="assessmentFor(space,r.requirement.id).status==='已达标'?'green':assessmentFor(space,r.requirement.id).status==='需加强'?'amber':''">{{assessmentFor(space,r.requirement.id).status}}</span></td><td>{{assessmentFor(space,r.requirement.id).reason}}<small v-if="requirementIssues(space,r.requirement.id).length" class="condition-note">定义条件待核对；不记作学生能力不足</small></td><td><button class="text-link" :aria-label="'查看学习要求 '+r.requirement.id" @click="show('requirement',r.requirement.id)">标准与依据 →</button></td></tr></tbody></table><p v-if="!requirements.length" class="empty">此范围尚无具体学习要求。</p></section>
          </template>
          <template v-else-if="!invalidFilter&&tab==='changes'">
            <div class="section-heading"><h3>个人判断的更新记录</h3><span class="muted">按活动当时的结果展示，不用当前状态回填</span></div>
            <section class="table-card scroll-table"><table class="data-table student-changes"><thead><tr><th>时间 / 活动</th><th>Task Claim</th><th>变化摘要</th><th></th></tr></thead><tbody><tr v-for="r in updates.slice((safePage(updates.length)-1)*10,safePage(updates.length)*10)" :key="r.id"><td>{{r.activity.at}}<small>{{r.activity.name}} · {{r.round.name}}</small></td><td>{{r.claim?.name||r.audit.claimId}}<small>当时采用 v{{r.claim?.version}}</small></td><td><p v-for="c in r.round.changes.filter(c=>c.before!==c.after)" :key="c.aspect">{{aspect(c.aspect)}}：{{c.before}} → {{c.after}}</p><span v-if="!r.round.changes.some(c=>c.before!==c.after)" class="muted">判断未变；保留本轮依据</span></td><td><button class="text-link" :aria-label="'查看判断变化 '+r.id" @click="show('change',r.id)">前后判断与依据 →</button></td></tr></tbody></table><p v-if="!updates.length" class="empty">所选期间和范围暂无判断更新记录。</p></section><PagingBar v-if="updates.length>10" :total="updates.length" :page="safePage(updates.length)"/>
            <details class="definition-history"><summary>课程采用记录与当前定义差异</summary><p class="muted">以下描述本空间整体的采用情况；定义或目标改变本身不表示学生学会了更多。</p><div v-for="(h,i) in spaceHistory" :key="i" class="list-row"><div>{{h.description}}<small>{{h.actor}} · {{h.at}}</small></div></div><p v-if="!spaceHistory.length" class="muted">所选期间没有采用记录。</p><div v-for="d in changes" :key="d.id" class="list-row"><div>{{d.kind}} · {{d.name}}<small>空间保留 {{d.version}}；当前目录 {{d.currentVersion}}。这是一项当前差异，不作为所选期间的个人能力变化。</small></div></div><p v-if="!changes.length" class="muted">当前目录与采用内容未记录差异。</p><button class="text-link" @click="owner('learning-spaces',{id:space.id})">查看采用内容与版本 →</button></details>
          </template>
          <template v-else-if="!invalidFilter&&tab==='activities'">
            <p class="muted">{{activities.length}} 次活动 · {{activities.reduce((n,r)=>n+r.activity.evidence.length,0)}} 条 Evidence。一次作答可形成多条 Evidence，不等于多次独立表现。</p>
            <section class="table-card scroll-table"><table class="data-table student-activities"><thead><tr><th>活动</th><th>实际帮助</th><th>Evidence</th><th>时间 / 处理与审查</th><th></th></tr></thead><tbody><tr v-for="r in activities.slice((safePage(activities.length)-1)*10,safePage(activities.length)*10)" :key="r.activity.id"><td>{{r.activity.name}}<small>{{chapterName(r.activity.chapterId)}} · {{r.activity.kind}}</small></td><td>{{r.activity.help}}</td><td><button v-for="e in r.activity.evidence" :key="e.id" class="text-link evidence-link" @click="show('evidence',e.id)">{{e.id}} →</button><span v-if="!r.activity.evidence.length" class="muted">本次无个人表现证据</span></td><td>{{r.activity.at}}<small>{{r.audit?executionNames[r.audit.execution]:'执行未记录'}} · {{r.audit?reviewNames[r.audit.review]:'复核未记录'}}</small></td><td><button class="text-link" :aria-label="'查看活动 '+r.activity.id" @click="trace(r.activity.id)">交互审查 →</button></td></tr></tbody></table><p v-if="!activities.length" class="empty">所选期间和范围没有学习活动，不借用其他空间的记录。</p></section><PagingBar v-if="activities.length>10" :total="activities.length" :page="safePage(activities.length)"/>
          </template>
          <WorkbenchDialog v-if="route.result" :key="route.result" :title="detailTitle" wide @close="setQuery({result:''})">
            <p class="muted">{{student.name}} · {{space.name}} · {{space.id}} · 只读示例</p>
            <template v-if="validDetail&&(detailKind==='belief'||detailKind==='definition')&&detailClaim">
              <h3>{{detailClaim.name}} · 采用 v{{detailClaim.version}}</h3><p class="muted">{{detailClaim.id}} · {{taskName(detailClaim.taskId)}}</p>
              <template v-if="detailKind==='belief'"><p class="lead">以下是同一 Claim 的各方面个人认识；不合成为一个总掌握分数。</p><section v-for="a in detailClaim.aspects" :key="a.id" class="belief-aspect"><h4>{{a.name}}</h4><p class="aspect-judgment">{{aspectText(space,detailClaim.id,a.id)}}</p><p class="muted">{{!a.applicable?a.reason:currentJudgment(space,detailClaim.id,a.id)?.uncertainty||'尚无足够个人证据，不能从其他方面的成功补齐。'}}</p><p v-if="currentJudgment(space,detailClaim.id,a.id)" class="muted">最近判断变化：{{aspectChangedAt(space,detailClaim.id,a.id)||'未记录'}} · 依据活动日期，不冒充正式修订时间</p><div class="button-row"><button v-for="id in currentJudgment(space,detailClaim.id,a.id)?.evidenceIds||[]" :key="id" class="text-link" @click="show('evidence',id)">{{id}} · 查看依据 →</button></div></section><p class="muted">本 Claim 当前引用 {{claimBasis(detailClaim.id).length}} 条去重 Evidence；数量不等于独立样本数。</p></template>
              <details :open="detailKind==='definition'"><summary>评价条件与定义依据</summary><dl class="field-list"><dt>任务范围</dt><dd>{{detailClaim.scope}}</dd><dt>方法条件</dt><dd>{{detailClaim.methodMode==='all'?'分别覆盖全部方法':'任选一种方法'}}：{{methodNames(detailClaim.methods)}}</dd><dt>允许的帮助</dt><dd>{{detailClaim.support}}</dd><template v-for="a in detailClaim.aspects" :key="a.id"><dt>{{a.name}}</dt><dd>{{a.applicable?a.criterion:'不适用：'+a.reason}}<small v-if="a.applicable">证据要求：{{a.evidence}}</small></dd></template></dl></details>
              <div class="dialog-footer"><p class="muted">这里展示空间采用的定义；打开管理页面查看当前定义，不覆盖个人历史。</p><button class="btn" @click="owner('evaluation',{id:detailClaim.id,tab:'definition'})">查看当前 Claim 定义 →</button></div>
            </template>
            <template v-else-if="validDetail&&detailKind==='evidence'&&detailEvidence"><h3>{{detailEvidence.evidence.id}} · {{aspect(detailEvidence.evidence.aspectId)}}</h3><p>{{detailEvidence.evidence.meaning}}</p><p class="callout">实际帮助：{{detailEvidence.activity.help}}</p><p class="muted">{{detailEvidence.activity.name}} · {{detailEvidence.activity.at}}</p><article v-for="(m,i) in detailEvidence.activity.messages" :key="i" class="audit-turn" :class="{user:m.actor==='学生'}"><header>{{m.actor}}</header><p>{{m.text}}</p></article><p class="muted">以上按原顺序显示；后续讲解不能倒算为作答前的帮助，也不能直接上调个人判断。</p><div class="dialog-footer button-row"><button class="btn" @click="show('belief',detailEvidence.evidence.claimId)">返回该 Claim 的个人判断</button><button class="btn primary" @click="evidenceTrace(detailEvidence.evidence.id)">查看源活动的解释步骤 →</button></div></template>
            <template v-else-if="validDetail&&detailKind==='requirement'&&detailRequirement"><h3>{{detailRequirement.requirement.name}}</h3><dl class="field-list"><dt>达标标准</dt><dd>{{detailRequirement.requirement.standard}}</dd><dt>当前目标结果</dt><dd>{{assessmentFor(space,detailRequirement.requirement.id).status}}<small>{{assessmentFor(space,detailRequirement.requirement.id).reason}}</small></dd><dt>所需评价方面</dt><dd>{{detailRequirement.requirement.aspectIds.map(aspect).join('、')}}</dd><dt>个人 Belief</dt><dd><p v-for="id in detailRequirement.requirement.aspectIds" :key="id">{{aspect(id)}}：{{aspectText(space,detailRequirement.selection.claimId,id)}}</p></dd></dl><p v-for="issue in requirementIssues(space,detailRequirement.requirement.id)" :key="issue" class="callout amber">{{issue}}</p><div class="dialog-footer button-row"><button class="btn" @click="show('belief',detailRequirement.selection.claimId)">查看个人判断与证据</button><button class="btn" @click="owner('targets',{id:space.adopted.target.id,claim:detailRequirement.selection.claimId})">查看当前目标要求 →</button></div></template>
            <template v-else-if="validDetail&&detailKind==='change'&&detailChange"><h3>{{detailChange.claim?.name}} · 当时采用 v{{detailChange.claim?.version}}</h3><p class="muted">{{detailChange.activity.at}} · {{detailChange.activity.name}} / {{detailChange.round.name}}</p><p class="callout">帮助条件：{{detailChange.round.help}}</p><section v-for="c in detailChange.round.changes" :key="c.aspect" class="belief-aspect"><h4>{{aspect(c.aspect)}}</h4><p>{{c.before}} → {{c.after}}</p><p class="muted">{{c.reason}}</p><div class="button-row"><button v-for="id in c.evidenceIds" :key="id" class="text-link" @click="show('evidence',id)">{{id}} · 查看依据 →</button></div></section><h4>当时的目标结果</h4><div v-for="r in detailChange.round.results" :key="r.id" class="list-row"><div>{{detailChange.audit.snapshot.target.claims.flatMap(s=>s.requirements).find(x=>x.id===r.id)?.name||r.id}}<small>{{r.before}} → {{r.after}} · {{r.reason}}</small></div></div><div class="dialog-footer"><button class="btn primary" @click="trace(detailChange.activity.id,detailChange.round.id,detailChange.round.id+'-belief')">追溯该轮 Belief 更新 →</button></div></template>
            <p v-else class="callout amber">此记录不存在或不属于当前学习空间，不用其他学生、空间或 Claim 的结果替代。</p>
          </WorkbenchDialog>
        </template>
      </AccessGate>
    </template>
  </template>
</div></template>
