anges th:nth-child(2){width:20%}.student-changes td p{margin:0 0 8px;font-size:12px}.student-changes th:last-child{width:125px}.student-activities th:first-child{width:24%}.student-activities th:nth-child(2){width:29%}.student-activities th:nth-child(4){width:150px}.evidence-link{display:block;margin-bottom:6px;white-space:nowrap}.belief-aspect{padding:8px 0 15px;border-bottom:1px solid #e1e8ed}.belief-aspect h4{margin:10px 0 8px}.belief-aspect p{font-size:13px;line-height:1.8;margin:7px 0}.belief-aspect .aspect-judgment{font-weight:600;color:#355f46}.definition-history{margin-bottom:24px}.goal-heading{margin-top:30px}.dialog-footer .muted{margin:0 0 10px}@media(max-width:1100px){.course-context{display:block}.course-context .button-row{margin-top:14px;justify-content:start}.section-heading{flex-wrap:wrap}.student-metrics{grid-template-columns:repeat(2,minmax(0,1fr))}.student-filters .search-label{max-width:none}.student-filters select{max-width:none}.goal-heading{align-items:start}}
